from math import isqrt, pi

# ═══════════════ Tunable constants ═══════════════
LIMIT       = 10_000     # sieve bound for primes
GOLD_LIMIT  = 4_000      # Goldbach: verify every even number up to here
COLL_LIMIT  = 1_000      # Collatz: starting values 2..COLL_LIMIT
SPR_SIZE    = 41         # Ulam spiral side length (odd)
MULT_SIZE   = 18         # digital-root multiplication table size
